package com.example.aspect;

import org.aspectj.lang.JoinPoint;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.After;
import org.aspectj.lang.annotation.AfterReturning;
import org.aspectj.lang.annotation.AfterThrowing;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.annotation.Before;
import org.aspectj.lang.annotation.Pointcut;
import org.springframework.stereotype.Component;

@Aspect
@Component
public class OrderAspect {

    @Pointcut("execution(* com.example.service.GreetService.*(..))")
    public void greet() {
    }

    @Around("greet()")
    public Object around(ProceedingJoinPoint pjp) throws Throwable {
        System.out.println("1 Around: 前段");
        try {
            Object result = pjp.proceed();
            System.out.println("4 Around: 后段, 返回值=" + result);
            return result;
        } finally {
            System.out.println("4.5 Around: finally");
        }
    }

    @Before("greet()")
    public void before(JoinPoint jp) {
        System.out.println("2 Before: " + jp.getSignature().getName());
    }

    @After("greet()")
    public void after() {
        System.out.println("5 After: 无论成败都执行");
    }

    @AfterReturning("greet()")
    public void afterReturning() {
        System.out.println("6 AfterReturning: 正常返回后");
    }

    @AfterThrowing("greet()")
    public void afterThrowing() {
        System.out.println("6': AfterThrowing: 抛异常后");
    }
}
// 正常执行输出顺序：1 → 2 → 目标方法 → 4 → 4.5 → 5 → 6

package com.example.aspect;

import java.util.concurrent.atomic.AtomicInteger;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.springframework.stereotype.Component;

@Aspect
@Component
public class RateLimitAspect {

    private final AtomicInteger counter = new AtomicInteger(0);
    private static final int MAX_CALLS = 3;

    @Around("execution(* com.example.service.HeavyService.work())")
    public Object limit(ProceedingJoinPoint pjp) throws Throwable {
        if (counter.incrementAndGet() > MAX_CALLS) {
            // 不调用 proceed()，目标方法根本不执行——这就是 Around 的权力
            return "限流: 请求过多";
        }
        return pjp.proceed();
    }
}
